@overload
def _to_rust_crawl_page_result(value: None) -> None: ...


@overload
def _to_rust_crawl_page_result(value: CrawlPageResult | dict[str, Any] | str) -> _rust.CrawlPageResult: ...
def _to_rust_crawl_page_result(value: CrawlPageResult | dict[str, Any] | str | None) -> _rust.CrawlPageResult | None:
    """Convert Python CrawlPageResult to Rust binding type."""
    if isinstance(value, str):
        value = json.loads(value)
    if isinstance(value, dict):
        if "metadata" in value and value["metadata"] is not None:
            value["metadata"] = _to_rust_page_metadata(value["metadata"])
        if "markdown" in value and value["markdown"] is not None:
            value["markdown"] = _to_rust_markdown_result(value["markdown"])
        if "extraction_meta" in value and value["extraction_meta"] is not None:
            value["extraction_meta"] = _to_rust_extraction_meta(value["extraction_meta"])
        if "downloaded_document" in value and value["downloaded_document"] is not None:
            value["downloaded_document"] = _to_rust_downloaded_document(value["downloaded_document"])
        value = CrawlPageResult(**value)
    if value is None:
        return None
    value = cast(CrawlPageResult, value)
    return _rust.CrawlPageResult(
        url=value.url,
        normalized_url=value.normalized_url,
        status_code=value.status_code,
        content_type=value.content_type,
        html=value.html,
        body_size=value.body_size,
        metadata=_to_rust_page_metadata(value.metadata),
        links=[_to_rust_link_info(v) for v in value.links],
        images=[_to_rust_image_info(v) for v in value.images],
        feeds=[_to_rust_feed_info(v) for v in value.feeds],
        json_ld=[_to_rust_json_ld_entry(v) for v in value.json_ld],
        depth=value.depth,
        stayed_on_domain=value.stayed_on_domain,
        was_skipped=value.was_skipped,
        is_pdf=value.is_pdf,
        detected_charset=value.detected_charset,
        markdown=_to_rust_markdown_result(value.markdown),
        extracted_data=(
            json.dumps(value.extracted_data) if isinstance(value.extracted_data, (dict, list)) else value.extracted_data
        ),
        extraction_meta=_to_rust_extraction_meta(value.extraction_meta),
        downloaded_document=_to_rust_downloaded_document(value.downloaded_document),
        browser_used=value.browser_used,
        final_url=value.final_url,
        redirect_count=value.redirect_count,
        noindex_detected=value.noindex_detected,
        nofollow_detected=value.nofollow_detected,
        ssrf_refused_urls=value.ssrf_refused_urls,
        original_url=value.original_url,
    )


