async def batch_crawl(engine: CrawlEngineHandle, urls: list[str]) -> BatchCrawlResults:
    """Crawl multiple seed URLs concurrently, each following links to configured depth."""
    return _from_native_batch_crawl_results(await _rust.batch_crawl(engine=engine, urls=urls))


async def batch_scrape(engine: CrawlEngineHandle, urls: list[str]) -> BatchScrapeResults:
    """Scrape multiple URLs concurrently."""
    return _from_native_batch_scrape_results(await _rust.batch_scrape(engine=engine, urls=urls))


async def crawl(engine: CrawlEngineHandle, url: str) -> CrawlResult:
    """Crawl a website starting from `url`, following links up to the configured depth."""
    return _from_native_crawl_result(await _rust.crawl(engine=engine, url=url))


def create_engine(config: CrawlConfig | None = None) -> _rust.CrawlEngineHandle:
    """Create a new crawl engine with the given configuration."""
    _rust_config = _to_rust_crawl_config(config) if config is not None else _rust.CrawlConfig()
    return _rust.create_engine(config=_rust_config)


def generate_citations(markdown: str) -> CitationResult:
    """Convert markdown links to numbered citations."""
    return _from_native_citation_result(_rust.generate_citations(markdown=markdown))


async def interact(
    engine: CrawlEngineHandle,
    url: str,
    actions: list[PageAction],
) -> InteractionResult:
    """Execute browser actions on a single page."""
    _rust_actions = [
        (_rust.PageAction(__item) if not isinstance(__item, _rust.PageAction) else __item) for __item in actions
    ]

    return _from_native_interaction_result(await _rust.interact(engine=engine, url=url, actions=_rust_actions))


async def map_urls(engine: CrawlEngineHandle, url: str) -> MapResult:
    """Discover all pages on a website by following links and sitemaps."""
    return _from_native_map_result(await _rust.map_urls(engine=engine, url=url))


async def scrape(engine: CrawlEngineHandle, url: str) -> ScrapeResult:
    """Scrape a single URL, returning extracted page data."""
    return _from_native_scrape_result(await _rust.scrape(engine=engine, url=url))


async def crawl_stream(
    engine: CrawlEngineHandle, url: str | CrawlStreamRequest | _rust.CrawlStreamRequest
) -> AsyncIterator[CrawlEvent]:
    """Crawl stream."""
    if isinstance(url, str):
        req = _rust.CrawlStreamRequest(url=url)
    elif isinstance(url, _rust.CrawlStreamRequest):
        req = url
    elif isinstance(url, CrawlStreamRequest):
        req = _to_rust_crawl_stream_request(url)
    else:
        raise TypeError("url must be str or a CrawlStreamRequest request")
    async for item in engine.crawl_stream(req):
        yield item


async def batch_crawl_stream(
    engine: CrawlEngineHandle, urls: list[str] | BatchCrawlStreamRequest | _rust.BatchCrawlStreamRequest
) -> AsyncIterator[CrawlEvent]:
    """Batch crawl stream."""
    if isinstance(urls, list):
        req = _rust.BatchCrawlStreamRequest(urls=urls)
    elif isinstance(urls, _rust.BatchCrawlStreamRequest):
        req = urls
    elif isinstance(urls, BatchCrawlStreamRequest):
        req = _to_rust_batch_crawl_stream_request(urls)
    else:
        raise TypeError("urls must be list or a BatchCrawlStreamRequest request")
    async for item in engine.batch_crawl_stream(req):
        yield item
